def inorder_successor(root, p):
    succ, node = None, root
    while node is not None:
        if node.val > p.val:
            succ = node                  # a candidate; look for a smaller one
            node = node.left
        else:
            node = node.right
    return succ

def inorder_successor(root, p):
    stack, node, seen_p = [], root, False
    while stack or node:
        while node:
            stack.append(node)
            node = node.left
        node = stack.pop()
        if seen_p:
            return node
        seen_p = node is p
        node = node.right
    return None
